<template><main class="login-page"><section class="login-visual"><div class="visual-content"><span>JTG 5120-2021</span><h1>公路桥梁初始检查信息系统</h1><p>桥梁档案、初始检查、定期检查、病害记录与报告统一管理。</p></div></section><section class="login-panel"><div class="login-card"><div class="login-tabs"><button :class="{active:mode==='login'}" @click="mode='login'">账号登录</button><button :class="{active:mode==='register'}" @click="mode='register'">用户注册</button></div><div class="login-title"><h2>{{ mode==='login'?'系统登录':'注册查询账号' }}</h2><p>{{ mode==='login'?'默认账号：admin / admin123':'注册成功后默认拥有查询人员权限' }}</p></div><el-form v-if="mode==='login'" :model="loginForm" label-position="top" @keyup.enter="submitLogin"><el-form-item label="登录账号"><el-input v-model="loginForm.account" size="large" placeholder="请输入账号"/></el-form-item><el-form-item label="登录密码"><el-input v-model="loginForm.password" size="large" type="password" show-password placeholder="请输入密码"/></el-form-item><el-button size="large" type="primary" class="login-button" :loading="loading" @click="submitLogin">登录</el-button></el-form><el-form v-else :model="registerForm" label-position="top"><div class="register-grid"><el-form-item label="登录账号"><el-input v-model="registerForm.account" placeholder="字母开头，4至30位"/></el-form-item><el-form-item label="真实姓名"><el-input v-model="registerForm.realName" placeholder="请输入姓名"/></el-form-item><el-form-item label="登录密码"><el-input v-model="registerForm.password" type="password" show-password placeholder="至少8位，含字母和数字"/></el-form-item><el-form-item label="确认密码"><el-input v-model="registerForm.confirmPassword" type="password" show-password placeholder="再次输入密码"/></el-form-item><el-form-item label="单位或部门"><el-input v-model="registerForm.department" placeholder="选填"/></el-form-item><el-form-item label="联系电话"><el-input v-model="registerForm.phone" placeholder="选填"/></el-form-item><el-form-item label="电子邮箱" class="full-row"><el-input v-model="registerForm.email" placeholder="选填"/></el-form-item></div><el-alert title="公开注册账号固定为查询人员。如需工程师、检查人员或审核人员权限，请联系管理员调整角色。" type="info" :closable="false" style="margin-bottom:16px"/><el-button size="large" type="primary" class="login-button" :loading="loading" @click="submitRegister">注册并返回登录</el-button></el-form></div></section></main></template>
<script setup>import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {useAuthStore} from '../stores/auth';import http from '../api/http';const router=useRouter(),auth=useAuthStore(),loading=ref(false),mode=ref('login');const loginForm=reactive({account:'admin',password:'admin123'});const registerForm=reactive({account:'',realName:'',password:'',confirmPassword:'',department:'',phone:'',email:''});async function submitLogin(){if(!loginForm.account||!loginForm.password){ElMessage.warning('请输入账号和密码');return}loading.value=true;try{const home=await auth.login(loginForm.account,loginForm.password);router.push(home)}finally{loading.value=false}}async function submitRegister(){if(!/^[A-Za-z][A-Za-z0-9_]{3,29}$/.test(registerForm.account)){ElMessage.warning('账号须以字母开头，只能包含字母、数字和下划线，长度4至30位');return}if(!registerForm.realName.trim()){ElMessage.warning('请输入真实姓名');return}if(!/^(?=.*[A-Za-z])(?=.*\d).{8,64}$/.test(registerForm.password)){ElMessage.warning('密码须为8至64位并同时包含字母和数字');return}if(registerForm.password!==registerForm.confirmPassword){ElMessage.warning('两次输入的密码不一致');return}loading.value=true;try{await http.post('/auth/register',registerForm);ElMessage.success('注册成功，请使用新账号登录');loginForm.account=registerForm.account;loginForm.password='';mode.value='login'}finally{loading.value=false}}</script>
<style scoped>.login-page{min-height:100vh;display:grid;grid-template-columns:minmax(0,1fr) 500px;background:#0f172a}.login-visual{position:relative;display:flex;align-items:flex-end;padding:56px;background:linear-gradient(0deg,rgba(15,23,42,.88),rgba(15,23,42,.22)),url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=80") center/cover}.visual-content{max-width:680px;color:#fff}.visual-content span{display:inline-flex;border:1px solid rgba(255,255,255,.35);border-radius:999px;padding:6px 12px;font-size:13px}.visual-content h1{margin:18px 0 12px;font-size:44px;line-height:1.16}.visual-content p{margin:0;color:#dbeafe;font-size:17px}.login-panel{display:grid;place-items:center;background:#f8fafc;padding:28px}.login-card{width:100%;max-height:calc(100vh - 56px);overflow:auto;padding:4px}.login-tabs{display:grid;grid-template-columns:1fr 1fr;background:#111827;border-radius:9px;padding:4px;margin-bottom:22px}.login-tabs button{border:0;border-radius:7px;padding:11px;background:#1f2937;color:#f8fafc;cursor:pointer}.login-tabs button.active{background:#f8fafc;color:#172033;font-weight:700}.login-title{margin-bottom:22px}.login-title h2{margin:0;font-size:28px}.login-title p{color:#64748b;margin:8px 0 0}.login-button{width:100%}.register-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.full-row{grid-column:1/-1}@media(max-width:900px){.login-page{grid-template-columns:1fr}.login-visual{min-height:34vh;padding:32px}.visual-content h1{font-size:32px}.login-card{max-height:none}}@media(max-width:560px){.register-grid{grid-template-columns:1fr}.full-row{grid-column:auto}}</style>
